sql_query:
SELECT "Primary endpoint"
FROM clinical_trials
WHERE "Included in MA" = 'No' AND "Name of ICI" = 'Pembrolizumab' AND "Trial phase" = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Primary endpoint" AS source_value FROM clinical_trials WHERE "Included in MA" = 'No' AND "Name of ICI" = 'Pembrolizumab' AND "Trial phase" = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_endpoint_role(source_value, 'Primary endpoint') AS "endpoint_role"
FROM base;
